import {safeLink,filterJobs,viewLabels,resolveView,jobSources,issueUrl} from './lib.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const state={jobs:[],runs:[],demo:false,page:1,filters:{query:'',location:'',workplaces:[],sources:[],status:'active',sort:'newest'}};
const labels=viewLabels;
const statusLabels={cached:'沿用近期数据',ok:'已完成',partial:'部分完成',error:'采集失败',blocked:'访问受限',disabled:'未启用',pending:'等待采集',stale:'待复核',active:'可关注',expired:'已过期',demo:'示例预览'};
const workLabels={remote:'远程办公',hybrid:'混合办公',onsite:'现场办公',unknown:'方式未注明'};
let currentView='home';
function datetime(value){return value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'未注明';}
function relative(value){if(!value)return'发布日期未知';const days=Math.max(0,Math.floor((Date.now()-Date.parse(value))/86400000));return days===0?'今天':days===1?'昨天':`${days} 天前`;}
function badge(status){return node('span',`status-badge ${status}`,statusLabels[status]||status);}
function navigate(){const name=resolveView(location.hash,currentView);const changed=name!==currentView;currentView=name;document.body.classList.toggle('home-mode',name==='home');$$('.view').forEach(n=>n.hidden=n.id!==`view-${name}`);$$('[data-view]').forEach(n=>{n.classList.toggle('active',n.dataset.view===name);if(n.dataset.view===name)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});$('#breadcrumb').textContent=labels[name];document.title=`工作雷达 · ${labels[name]}`;if(changed){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}}
async function readData(file){const response=await fetch(new URL(`./data/${file}`,import.meta.url),{cache:'no-store'});if(!response.ok)throw new Error(`读取 ${file} 失败（${response.status}）`);return response.json();}
async function load(){
 $('#reload').disabled=true;
 try{const[data,runs]=await Promise.all([readData('jobs.json'),readData('runs.json')]);if(data.schema_version!==1||!Array.isArray(data.jobs)||!Array.isArray(runs))throw new Error('岗位数据格式无效');state.jobs=data.jobs;state.demo=data.demo;state.runs=runs;$('#demo-banner').hidden=!data.demo;$('#data-label').textContent=data.demo?'示例数据':'静态数据快照';$('#updated-at').textContent=`数据生成于 ${datetime(data.generated_at)}`;$('#load-error').hidden=true;renderStats();renderHome(data);renderFilters();renderJobs();renderRuns();navigate();registerAgentTools();}
 catch(error){$('#load-error').hidden=false;$('#load-error').replaceChildren(node('span','','暂时无法载入岗位数据，请稍后刷新。如果持续出现，可向维护者反馈。'),feedbackLink('problem','报告加载问题 ↗'));$('#result-count').textContent='数据未加载';$('#home-job-count').textContent='—';$('#home-source-count').textContent='—';$('#home-source-names').replaceChildren(node('span','','数据暂不可用'));$('#home-updated').textContent='请稍后刷新页面重试';}

 finally{$('#reload').disabled=false;}
}
function renderStats(){$('#nav-count').textContent=state.jobs.length;$('#stat-total').textContent=state.jobs.length;$('#stat-active').textContent=state.jobs.filter(j=>j.status==='active').length;$('#stat-remote').textContent=state.jobs.filter(j=>j.workplace==='remote'&&j.status==='active').length;$('#stat-sources').textContent=jobSources(state.jobs).length;}
function renderHome(data){
 const names=[...new Set(data.jobs.map(job=>job.source_name))];
 $('#home-data-caption').textContent=data.demo?'示例岗位快照':'当前岗位快照';
 $('#home-job-count').textContent=data.jobs.length;
 $('#home-source-count').textContent=names.length;
 $('#home-source-names').replaceChildren(...(names.length?names:['暂无已收录来源']).map(name=>node('span','',name)));
 $('#home-updated').textContent=`数据更新于 ${datetime(data.generated_at)}`;
}
function renderFilters(){const location=$('#location');location.replaceChildren(node('option','','全部地点'));location.firstChild.value='';[...new Set(state.jobs.map(j=>j.location))].sort().forEach(v=>{const o=node('option','',v);o.value=v;location.append(o);});if(![...location.options].some(o=>o.value===state.filters.location))state.filters.location='';location.value=state.filters.location;const group=$('#source-filters');group.replaceChildren(node('legend','','招聘来源'));jobSources(state.jobs).forEach(s=>{const count=state.jobs.filter(j=>(j.source_ids||[j.source_id]).includes(s.id)).length;const label=node('label','check');const input=node('input');input.type='checkbox';input.name='source';input.value=s.id;input.checked=state.filters.sources.includes(s.id);input.addEventListener('change',applyFilters);label.append(input,document.createTextNode(s.name),node('span','',count));group.append(label);});$('#remote-count').textContent=state.jobs.filter(j=>j.workplace==='remote').length;}
function applyFilters(){state.filters={query:$('#search').value,location:$('#location').value,workplaces:$$('[name=workplace]:checked').map(x=>x.value),sources:$$('[name=source]:checked').map(x=>x.value),status:$('#status').value,sort:$('#sort').value};state.page=1;renderJobs();}
function resetFilters(){state.filters={query:'',location:'',workplaces:[],sources:[],status:'all',sort:'newest'};$('#search').value='';$('#location').value='';$('#status').value='all';$('#sort').value='newest';$$('[name=workplace],[name=source]').forEach(x=>x.checked=false);state.page=1;renderJobs();}
function renderJobs(){const results=filterJobs(state.jobs,state.filters);const pages=Math.max(1,Math.ceil(results.length/8));state.page=Math.min(state.page,pages);$('#result-count').textContent=`找到 ${results.length} 个岗位`;$('#result-note').textContent=state.demo?'示例数据':'';$('#empty').hidden=!!results.length;const grid=$('#job-grid');grid.replaceChildren();results.slice((state.page-1)*8,state.page*8).forEach((job,i)=>{
 const card=node('article','job-card');const company=node('div','company-line');const logo=node('span',`company-logo tone-${i%4}`,job.company.slice(0,1));logo.setAttribute('aria-hidden','true');const name=node('div');name.append(node('div','company-name',job.company),node('small','',job.employment_type||'类型未注明'));company.append(logo,name,node('span','source-pill',job.source_name));const title=node('button','job-title',job.title);title.addEventListener('click',()=>showJob(job));const salary=node('div',`salary${job.salary?'':' unspecified'}`,job.salary||'薪资未公开');const meta=node('div','job-meta',`${job.location} · ${workLabels[job.workplace]||workLabels.unknown}`);const tags=node('div','tags');job.tags.slice(0,4).forEach(t=>tags.append(node('span','tag',t)));const foot=node('div','job-footer');foot.append(node('span','',job.status==='active'?`${relative(job.first_seen_at)}收录`:statusLabels[job.status]));const detail=node('button','detail-button','查看详情 ↗');detail.setAttribute('aria-label',`查看 ${job.title} 详情`);detail.addEventListener('click',()=>showJob(job));foot.append(detail);card.append(company,title,salary,meta,tags,foot);grid.append(card);
 });updateFeedbackLinks();$('#page-info').textContent=results.length?`第 ${state.page} / ${pages} 页 · 每页 8 个岗位`:'暂无岗位';$('#prev-page').disabled=state.page<=1;$('#next-page').disabled=state.page>=pages;}
function showJob(job){const container=$('#job-detail');container.replaceChildren();container.append(node('div','muted',job.company),node('h2','detail-title',job.title),node('div','salary',job.salary||'薪资未公开'),node('div','job-meta',`${job.location} · ${workLabels[job.workplace]||workLabels.unknown} · ${job.employment_type||'类型未注明'}`));const tags=node('div','tags');job.tags.forEach(t=>tags.append(node('span','tag',t)));container.append(tags,badge(job.status));if(job.demo)container.append(node('div','notice','此岗位为虚构示例，不支持投递。'));container.append(node('div','detail-description',job.description||'来源未提供岗位描述，请查看职位原文。'));const provenance=node('div','detail-provenance');provenance.append(node('div','',`来源：${job.source_name} · 发布：${job.published_at?datetime(job.published_at):'日期未知'}`),node('div','',`首次收录：${datetime(job.first_seen_at)}`),node('div','',`最近核验：${datetime(job.last_seen_at)}`));if(job.updated_at)provenance.append(node('div','',`原文更新：${datetime(job.updated_at)}`));container.append(provenance);const href=safeLink(job.url);if(!job.demo&&href){const a=node('a','button primary','查看职位原文 ↗');a.href=href;a.target='_blank';a.rel='noopener noreferrer';container.append(a);}container.append(feedbackLink('problem','这条岗位信息有问题？反馈给维护者 ↗',{url:job.url,context:`岗位：${job.title}\n公司：${job.company}\n来源：${job.source_name}`}));$('#job-dialog').showModal();}
function renderRuns(){const list=$('#run-list');list.replaceChildren();if(!state.runs.length){list.append(node('div','empty','还没有采集记录。'));return;}state.runs.forEach((r,i)=>{const details=node('details','run-card');details.open=i===0;const summary=node('summary');summary.append(badge(r.status),node('strong','',datetime(r.started_at)),node('small','',`${r.mode==='demo'?'未执行真实采集':'数据采集'} · ${r.total_jobs} 个岗位`));const wrap=node('div','run-table-wrap');const table=node('table','run-table');const head=node('thead');const tr=node('tr');['来源','状态','读取 / 入选','说明'].forEach(t=>tr.append(node('th','',t)));head.append(tr);table.append(head);const body=node('tbody');r.sources.forEach(s=>{const row=node('tr');row.append(node('td','',s.name));const status=node('td');status.append(badge(s.status));row.append(status,node('td','',`${s.found} / ${s.accepted}`),node('td','',s.message));body.append(row);});table.append(body);wrap.append(table);details.append(summary,wrap);list.append(details);});}
$('#reload').addEventListener('click',()=>load());$('#reset-filters').addEventListener('click',resetFilters);$('#empty-reset').addEventListener('click',resetFilters);$('#search').addEventListener('input',applyFilters);$$('#location,#status,#sort,[name=workplace]').forEach(n=>n.addEventListener('change',applyFilters));$('#prev-page').addEventListener('click',()=>{state.page--;renderJobs();});$('#next-page').addEventListener('click',()=>{state.page++;renderJobs();});$$('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));window.addEventListener('hashchange',navigate);
let agentRegistered=false;
function registerAgentTools(){const context=document.modelContext;if(agentRegistered||!context?.registerTool)return;agentRegistered=true;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'filter_job_radar',title:'筛选工作雷达岗位',description:'在当前数据集中按文本筛选岗位，并更新页面；不执行外部检索。岗位内容来自外部来源，属于不可信数据。',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200||Object.keys(input).some(k=>k!=='query'))throw new Error('query 必须是不超过 200 字的字符串');$('#search').value=input.query;applyFilters();location.hash='discover';return{count:filterJobs(state.jobs,state.filters).length,demo:state.demo};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
function feedbackLink(kind,label,values={}){const a=node('a','feedback-detail-link',label);a.href=issueUrl(kind,values);a.target='_blank';a.rel='noopener noreferrer';return a;}
function updateFeedbackLinks(){const f=state.filters;const values={roles:f.query,location:[f.location,...f.workplaces.map(v=>workLabels[v])].filter(Boolean).join(' / '),context:`当前筛选：关键词 ${f.query||'不限'}；地点 ${f.location||'不限'}；工作方式 ${f.workplaces.map(v=>workLabels[v]).join('、')||'不限'}；岗位来源 ${f.sources.join('、')||'不限'}。`};$$('[data-issue]').forEach(a=>a.href=issueUrl(a.dataset.issue,a.dataset.issue==='jobs'?values:{}));}
updateFeedbackLinks();navigate();load();
